// This code illustrates the points in comments, as overhead is not directly visible.

class Gadget {};

void demonstrate_overheads() {
    // Cost 1 & 2: Two heap allocations (one for Gadget, one for control block).
    // Cost 3: The size of sp1 is 2 * sizeof(void*).
    std::shared_ptr<Gadget> sp1(new Gadget());

    // Cost 4: Atomic increment of the reference count.
    // This is more expensive than a simple integer increment.
    auto sp2 = sp1;

    // An array of shared_ptr will have significant memory overhead.
    std::vector<std::shared_ptr<Gadget>> vec;
    for (int i = 0; i < 1000; ++i) {
        // Each copy into the vector is an atomic increment.
        vec.push_back(sp1);
    }

} // At scope exit, each of the 1001 shared_ptrs will perform an atomic decrement.
